"""Export a self-contained, private, text flashcard review file."""
import json
from pathlib import Path

REPO=Path(__file__).resolve().parents[2]
OUT=REPO.parent/'output'
OUT.mkdir(exist_ok=True)
cards=json.loads((REPO/'src/data/flashcardsChemCh3AhmedNadawiEn.text.json').read_text())
topics=json.loads((REPO/'src/data/flashcardsChemCh3AhmedNadawiEn.topics.json').read_text())
payload=json.dumps({'cards':cards,'topics':topics},ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
HTML='''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Tamayzak · Ionic Equilibrium Flashcards</title>
<style>
:root{font-family:system-ui,-apple-system,Arial,sans-serif;color:#163a73;background:#f6f3eb;color-scheme:light}*{box-sizing:border-box}body{margin:0}main{max-width:880px;margin:auto;padding:28px 20px 48px}header{margin-bottom:24px}.brand{font-weight:800;letter-spacing:.16em;font-size:12px}h1{font-size:clamp(25px,5vw,36px);letter-spacing:-.035em;margin:12px 0 6px}header p{margin:0;color:#63718a;font-size:14px}.tools{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0 16px}label{font-size:12px;font-weight:700;display:block}select,input{width:100%;min-height:45px;margin-top:6px;padding:10px;border:1px solid #c8ced8;border-radius:12px;background:#fff;color:#163a73;font:inherit;font-size:14px}.full{grid-column:1/-1}.card{padding:24px;border-radius:22px;border:1px solid #d4dae2;background:white;box-shadow:0 12px 40px #163a730b}.meta{display:flex;justify-content:space-between;gap:12px;font-size:11px;color:#64738c;text-transform:uppercase;letter-spacing:.12em}.question{font-size:20px;font-weight:650;line-height:1.65;white-space:pre-line;overflow-wrap:anywhere}.answer{border-top:1px solid #e2e6eb;padding-top:20px;margin-top:20px;max-height:65vh;overflow-y:auto;overscroll-behavior:contain}.answer p{white-space:pre-line;line-height:1.9;font-size:17px;overflow-wrap:anywhere}.math-scroll{overflow-x:auto;max-width:100%;border:1px solid #dce3ec;border-radius:12px;padding:14px;margin:16px 0;background:#f7f9fc}.math{position:relative;font-family:serif;user-select:text}.run{position:absolute;white-space:pre;line-height:1;transform-origin:left top}.rule{position:absolute;border-top:1px solid;pointer-events:none}button{font:inherit;cursor:pointer;min-height:46px;border-radius:12px;border:1px solid #ccd4df;padding:11px 16px;background:#fff;color:#163a73;font-weight:650}button:focus-visible,select:focus-visible,input:focus-visible,.math-scroll:focus-visible{outline:3px solid #7399dc;outline-offset:3px}button:disabled{opacity:.4;cursor:default}.primary{background:#163a73;color:#fff;border-color:#163a73;width:100%;margin-top:20px}.nav{display:flex;justify-content:space-between;gap:12px;margin-top:14px}.hint{font-size:12px;color:#758198;line-height:1.6}.answer[hidden]{display:none}.empty{padding:60px 20px;text-align:center}footer{margin-top:20px;font-size:12px;color:#758198;line-height:1.7}@media(max-width:520px){main{padding:20px 14px}.tools{grid-template-columns:1fr}.full{grid-column:auto}.card{padding:20px}.question{font-size:18px}.answer p{font-size:16px}.nav button{flex:1}}
</style>
<main><header><span class="brand">TAMAYZAK · تميزك</span><h1>Ionic Equilibrium</h1><p>Ahmed Al-Nadawi · English Chemistry · Chapter 3</p></header>
<div class="tools"><label>Topic<select id="topic"><option value="all">All topics</option></select></label><label>Find a question<input id="search" type="search" placeholder="Search questions…"></label><label class="full">Go to flashcard<select id="jump"></select></label></div>
<section class="card" aria-label="Text flashcard"><div class="meta"><span id="topic-name"></span><span id="counter"></span></div><p id="question" class="question" dir="auto"></p><section id="answer" class="answer" hidden aria-label="Answer"></section><button class="primary" id="reveal" aria-expanded="false">Reveal answer</button><p class="hint">Select text to copy it. Longer calculations scroll horizontally.</p></section>
<div class="nav"><button id="previous">← Previous</button><button id="shuffle">Shuffle</button><button id="next">Next →</button></div>
<footer><span id="count"></span> text flashcards · 12 topics. Original Arabic notes are retained where present in the source. Unworked source assignments are excluded from the solved deck.</footer></main>
<script id="deck" type="application/json">PAYLOAD</script>
<script>
const {cards,topics}=JSON.parse(document.getElementById('deck').textContent);
const $=id=>document.getElementById(id), context=document.createElement('canvas').getContext('2d'), scale=1.2;
let selected=[...cards],position=0,revealed=false;
for(const topic of topics){const o=document.createElement('option');o.value=topic.key;o.textContent=topic.title+' ('+cards.filter(c=>c.topic===topic.key).length+')';$('topic').append(o)}
$('count').textContent=cards.length;
function renderBlocks(blocks){$('answer').replaceChildren();for(const b of blocks){if(b.type==='text'){const p=document.createElement('p');p.dir='auto';p.textContent=b.text;$('answer').append(p);continue}const outer=document.createElement('div');outer.className='math-scroll';outer.tabIndex=0;outer.setAttribute('aria-label','Calculation');const inner=document.createElement('div');inner.className='math';inner.style.width=b.width*scale+'px';inner.style.height=b.height*scale+'px';for(const r of b.runs){const span=document.createElement('span');span.className='run';span.textContent=r.t;let ratio=1;if(context&&r.w){context.font=r.s*scale+'px serif';const width=context.measureText(r.t).width;if(width)ratio=r.w*scale/width}Object.assign(span.style,{left:r.x*scale+'px',top:(r.y-r.s*.82)*scale+'px',fontSize:r.s*scale+'px',transform:'scaleX('+ratio+')'});inner.append(span)}for(const [x,y,w] of b.rules){const line=document.createElement('span');line.className='rule';line.setAttribute('aria-hidden','true');Object.assign(line.style,{left:x*scale+'px',top:y*scale+'px',width:w*scale+'px'});inner.append(line)}outer.append(inner);$('answer').append(outer)}}
function draw(){revealed=false;$('answer').hidden=true;$('answer').replaceChildren();$('reveal').textContent='Reveal answer';$('reveal').setAttribute('aria-expanded','false');const c=selected[position];$('previous').disabled=!c||position===0;$('next').disabled=!c||position===selected.length-1;$('reveal').disabled=!c;$('counter').textContent=c?(position+1)+' / '+selected.length:'0 / 0';$('question').textContent=c?c.q:'No matching questions.';$('topic-name').textContent=c?topics.find(t=>t.key===c.topic).title:'';$('jump').value=String(position);if(c)try{localStorage.setItem('tamayzak-ch3-text-card',c.id)}catch{}}
function rebuild(){const q=$('search').value.toLowerCase().trim();selected=cards.filter(c=>($('topic').value==='all'||c.topic===$('topic').value)&&(!q||c.q.toLowerCase().includes(q)));position=0;$('jump').replaceChildren();selected.forEach((c,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+'. '+c.q.replace(/\\s+/g,' ').slice(0,100);$('jump').append(o)});draw()}
$('topic').addEventListener('change',rebuild);$('search').addEventListener('input',rebuild);$('jump').addEventListener('change',()=>{position=Number($('jump').value);draw()});$('reveal').onclick=()=>{if(!selected[position])return;revealed=!revealed;if(revealed)renderBlocks(selected[position].answerBlocks);$('answer').hidden=!revealed;$('reveal').textContent=revealed?'Hide answer':'Reveal answer';$('reveal').setAttribute('aria-expanded',String(revealed))};$('next').onclick=()=>{if(position<selected.length-1){position++;draw()}};$('previous').onclick=()=>{if(position>0){position--;draw()}};$('shuffle').onclick=()=>{for(let i=selected.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[selected[i],selected[j]]=[selected[j],selected[i]]}position=0;$('jump').replaceChildren();selected.forEach((c,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+'. '+c.q.replace(/\\s+/g,' ').slice(0,100);$('jump').append(o)});draw()};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName))return;if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('previous').click()});let remembered;try{remembered=localStorage.getItem('tamayzak-ch3-text-card')}catch{}rebuild();const rememberedIndex=selected.findIndex(c=>c.id===remembered);if(rememberedIndex>=0){position=rememberedIndex;draw()}
</script></html>'''
path=OUT/'Ahmed_Al_Nadawi_CH3_Text_Flashcards.html'
path.write_text(HTML.replace('PAYLOAD',payload))
print(str(path),path.stat().st_size)
